// Extract input college names and split into individual items
const firstItem = $input.first()?.json || {};
let raw = firstItem.colleges || firstItem['College or University Names (one per line)'] || '';

if (Array.isArray(raw)) {
  raw = raw.join('\n');
}

// Support actual newlines, escaped newlines \n, and carriage returns
const lines = String(raw || '')
  .split(/(?:\r\n|\r|\n|\\n)/)
  .map(l => l.trim())
  .filter(l => l.length > 1);

const seen = new Set();
const items = [];

for (const name of lines) {
  // Strip leading list numbers like "1. ", "1) ", "- "
  const cleanName = name.replace(/^[0-9]+[.\s)-]+/, '').replace(/^[-*•]\s*/, '').trim();
  const lower = cleanName.toLowerCase();
  if (cleanName && !seen.has(lower)) {
    seen.add(lower);
    items.push({
      json: {
        college: cleanName
      }
    });
  }
}

if (items.length === 0) {
  return [{ json: { college: 'Georgia Southern University' } }];
}

return items;

// Search, classify, and live-verify official nursing faculty directory pages
const items = $input.all();
let settings = {};
try {
  settings = $('Workflow Settings & API Keys').first()?.json || {};
} catch (e) {}

const geminiApiKey = settings.geminiApiKey || 'YOUR_GEMINI_API_KEY';
const geminiUrl = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash-lite:generateContent?key=' + geminiApiKey;

const knownVerifiedDirectories = {
  // Berry College
  'berry college': 'https://www.berry.edu/academics/fs/departments/nursing',
  'berry.edu': 'https://www.berry.edu/academics/fs/departments/nursing',

