  // Brewton-Parker College
  'brewton-parker': 'https://www.bpc.edu/faculty-and-staff-directory/',
  'bpc.edu': 'https://www.bpc.edu/faculty-and-staff-directory/',

  // Cambridge College
  'cambridge college': 'https://www.cambridgehealth.edu/campus-contacts/',
  'cambridgehealth.edu': 'https://www.cambridgehealth.edu/campus-contacts/',

