  'chamberlain.edu': 'https://www.chamberlain.edu/nursing-school/georgia',

  // Chattahoochee Tech
  'chattahoochee technical': 'https://www.chattahoocheetech.edu/contact-us/directory.html',
  'chattahoocheetech.edu': 'https://www.chattahoocheetech.edu/contact-us/directory.html',

  // Clayton State & Clayton College and State
  'clayton state': 'https://www.clayton.edu/health/nursing/faculty-and-research.php',
  'clayton college': 'https://www.clayton.edu/health/nursing/faculty-and-research.php',
  'clayton.edu': 'https://www.clayton.edu/health/nursing/faculty-and-research.php',

  // Coastal Pines Tech
