  'dalton state': 'https://www.daltonstate.edu/academics/school-of-health-professions/faculty-staff.cms',
  'gordon state': 'https://www.gordonstate.edu/academics/academic-schools/school-of-nursing-health-sciences/faculty-and-staff.html',
  'middle georgia': 'https://www.mga.edu/health-natural-sciences/nursing/faculty-staff.php',
