};

function isHospital(name) {
  return /medical center|health system|healthcare system|health care system|hospital|va health|infirmary|health care center|clinic\b/i.test(name);
}

const colleges = [];
for (const item of items) {
  const c = (item.json.college || '').trim();
  if (c && !colleges.includes(c)) colleges.push(c);
}

if (colleges.length === 0) return [];

async function pingUrl(url) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: url,
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
      },
      timeout: 3000,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true
    });
    const status = res.statusCode || res.status || 200;
    return { url, status };
  } catch (e) {
    return { url, status: 0 };
  }
}

const results = [];
const needLookup = [];

for (let i = 0; i < colleges.length; i++) {
  const college = colleges[i];
  if (isHospital(college)) {
    results.push({
      index: i,
      json: {
        'College Name': college,
        'Nursing Faculty Directory URL': 'N/A (Hospital / Medical Center - No Academic Faculty Directory)'
      }
    });
    continue;
  }

  const lower = college.toLowerCase();
  let matchedOvr = null;
  for (const [k, v] of Object.entries(knownVerifiedDirectories)) {
    if (lower.includes(k)) {
      matchedOvr = v;
      break;
    }
  }

  if (matchedOvr) {
    results.push({
      index: i,
      json: {
        'College Name': college,
        'Nursing Faculty Directory URL': matchedOvr
      }
    });
    continue;
  }

  needLookup.push({ id: i, name: college });
}

if (needLookup.length > 0) {
  const prompt = `You are an expert higher education researcher specializing in college nursing department directories.
Given this list of institutions:
${JSON.stringify(needLookup, null, 2)}

For each institution:
1. "id": must match input "id" exactly.
2. "name": the input institution name.
3. "type": one of ["college", "hospital", "merged"].
   - If it is a clinical hospital, medical center, or VA health system, type="hospital" and directory_url="N/A (Hospital / Medical Center - No Academic Faculty Directory)".
   - If it was merged or renamed, provide the active parent university's nursing directory.
4. "official_domain": the real, authentic web domain of the college (e.g. "berry.edu", "brenau.edu", "bpc.edu", "cambridgehealth.edu", "centralgatech.edu", "chamberlain.edu", "chattahoocheetech.edu", "clayton.edu", "coastalpines.edu"). NEVER fabricate domains by stripping spaces.
5. "directory_url": the best official nursing faculty/staff directory URL or departmental faculty URL on their official website.
6. "candidates": an array of 2-3 alternate directory/contact URLs on their official domain.

Respond ONLY with a valid JSON array of objects with keys: id, name, type, official_domain, directory_url, candidates.`;

  let llmItems = [];
  try {
    const resRaw = await this.helpers.httpRequest({
      method: 'POST',
      url: geminiUrl,
      headers: { 'Content-Type': 'application/json' },
      body: {
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: {
          temperature: 0.1,
          responseMimeType: 'application/json'
        }
      },
      timeout: 15000
    });

    const res = typeof resRaw === 'string' ? JSON.parse(resRaw) : resRaw;
    const rawText = res?.candidates?.[0]?.content?.parts?.[0]?.text || '[]';
    try {
      llmItems = JSON.parse(rawText);
    } catch (parseErr) {
      const jsonMatch = rawText.match(/\[[\s\S]*\]/);
      if (jsonMatch) {
        llmItems = JSON.parse(jsonMatch[0]);
      }
    }
  } catch (err) {}

  for (const item of needLookup) {
    const llm = (Array.isArray(llmItems) && llmItems.find(x => x.id === item.id)) ||
                (Array.isArray(llmItems) && llmItems.find(x => (x.name || x.institution || x.college || '').toLowerCase() === item.name.toLowerCase())) ||
                {};

    if (llm.type === 'hospital' || isHospital(item.name)) {
      results.push({
        index: item.id,
        json: {
          'College Name': item.name,
          'Nursing Faculty Directory URL': 'N/A (Hospital / Medical Center - No Academic Faculty Directory)'
        }
      });
      continue;
    }

    const domain = (llm.official_domain || llm.domain || '').toLowerCase().replace(/^www\./, '').trim();
    const cands = [];
    if (llm.directory_url && llm.directory_url.startsWith('http')) cands.push(llm.directory_url);
    if (Array.isArray(llm.candidates)) {
      for (const c of llm.candidates) {
        if (c && c.startsWith('http') && !cands.includes(c)) cands.push(c);
      }
    }
    if (domain) {
      cands.push(`https://${domain}/directory/`);
      cands.push(`https://${domain}/faculty-staff-directory/`);
    }

    let selectedUrl = null;
    if (cands.length > 0) {
      const nursingCands = cands.filter(u => /nurs/i.test(u));
      const otherCands = cands.filter(u => !/nurs/i.test(u));
      const topCands = [...nursingCands, ...otherCands].slice(0, 4);
      const pings = await Promise.all(topCands.map(u => pingUrl.call(this, u)));
      for (const p of pings) {
        if (p.status === 200 || p.status === 403) {
          selectedUrl = p.url;
          break;
        }
      }
    }

    if (!selectedUrl) {
      if (llm.directory_url && llm.directory_url.startsWith('http')) {
        selectedUrl = llm.directory_url;
      } else if (domain) {
        selectedUrl = `https://${domain}/directory/`;
      } else {
        selectedUrl = `https://www.google.com/search?q=${encodeURIComponent(item.name + ' nursing faculty directory')}`;
      }
    }

    results.push({
      index: item.id,
      json: {
        'College Name': item.name,
        'Nursing Faculty Directory URL': selectedUrl
      }
    });
  }
}

results.sort((a, b) => a.index - b.index);
return results.map(r => ({ json: r.json }));

const items = $input.all();
const total = items.length;
