let hospitals = 0;

for (const it of items) {
  const u = it.json['Nursing Faculty Directory URL'] || '';
  if (u.startsWith('http')) dirs++;
  else hospitals++;
}

const rowsHtml = items.map((item) => {
  const college = item.json['College Name'] || '';
  const url = item.json['Nursing Faculty Directory URL'] || '';
  const isLink = url.startsWith('http');
  const urlHtml = isLink 
    ? '<a class="dir-link" href="' + url + '" target="_blank" rel="noopener noreferrer">' + url + ' <span class="ext-icon">↗</span></a>'
    : '<span class="na-badge">🏥 Hospital / Medical Center — No Academic Directory</span>';

  return '<tr>' +
    '<td class="col-name">' + college + '</td>' +
    '<td class="col-url">' + urlHtml + '</td>' +
  '</tr>';
}).join('\n');

